// PortStat describes a listening port and the addresses where it was reachable.
type PortStat struct {
	BindAddress     string   `json:"bindAddress"`
	Port            string   `json:"port"`
	PortReachableTo []string `json:"portReachableTo"`
}

// NewPortStat parses a listening address and port.
func NewPortStat(ipPort string) (*PortStat, error) {
	stat := &PortStat{}
	if ipPort == "" {
		return stat, nil
	}
	address, port, err := net.SplitHostPort(ipPort)
	if err != nil || address == "" || port == "" || strings.Contains(port, ":") || strings.ContainsAny(address, "[]") {
		return nil, xerrors.Errorf("Invalid listening port: %s", ipPort)
	}
	// SplitHostPort accepts unbracketed hostnames and IPv4 addresses, and
	// bracketed IPv6 addresses. Preserve the brackets used in scan output.
	if strings.HasPrefix(ipPort, "[") {
		address = "[" + address + "]"
	}
	stat.BindAddress, stat.Port = address, port
	return stat, nil
}

// HasReachablePort reports whether a listening port was reachable.
func (p Package) HasReachablePort() bool {
	for _, ap := range p.AffectedProcs {
		for _, lp := range ap.ListenPortStats {
			if len(lp.PortReachableTo) > 0 {
				return true
			}
		}
	}

	return false
}

